-- NEXA complete inventory backend. Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.inventory_ingredients(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,name text not null,sku text,unit text not null default 'pcs',current_qty numeric(14,3) not null default 0,min_qty numeric(14,3) not null default 0,avg_cost numeric(14,4) not null default 0,active boolean not null default true,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(branch_id,name));
create table if not exists public.inventory_suppliers(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,name text not null,phone text,address text,opening_balance numeric(14,2) default 0,active boolean default true,created_at timestamptz default now());
create table if not exists public.inventory_purchases(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,supplier_id uuid references public.inventory_suppliers(id),invoice_no text,notes text,total_amount numeric(14,2) not null default 0,status text not null default 'POSTED',created_by uuid,created_at timestamptz default now());
create table if not exists public.inventory_purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.inventory_purchases(id) on delete cascade,ingredient_id uuid not null references public.inventory_ingredients(id),quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(14,4) not null default 0,total numeric(14,2) generated always as (quantity*unit_cost) stored);
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,ingredient_id uuid not null references public.inventory_ingredients(id),type text not null,quantity numeric(14,3) not null,unit_cost numeric(14,4) default 0,balance_after numeric(14,3),reference_type text,reference_id uuid,notes text,created_by uuid,created_at timestamptz default now());
create index if not exists inventory_movements_branch_date on public.inventory_movements(branch_id,created_at desc);
create table if not exists public.inventory_wastage(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,ingredient_id uuid not null references public.inventory_ingredients(id),quantity numeric(14,3) not null check(quantity>0),reason text,notes text,created_by uuid,created_at timestamptz default now());
create table if not exists public.inventory_recipes(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,name text not null,product_id uuid,variant_id uuid,yield_qty numeric(14,3) default 1,active boolean default true,created_by uuid,created_at timestamptz default now());
create table if not exists public.inventory_recipe_items(id uuid primary key default gen_random_uuid(),recipe_id uuid not null references public.inventory_recipes(id) on delete cascade,ingredient_id uuid not null references public.inventory_ingredients(id),quantity numeric(14,3) not null,wastage_pct numeric(8,3) default 0,unique(recipe_id,ingredient_id));
create table if not exists public.inventory_closings(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,notes text,created_by uuid,created_at timestamptz default now());
create table if not exists public.inventory_closing_items(id uuid primary key default gen_random_uuid(),closing_id uuid not null references public.inventory_closings(id) on delete cascade,ingredient_id uuid not null references public.inventory_ingredients(id),system_qty numeric(14,3) not null,physical_qty numeric(14,3) not null,variance numeric(14,3) not null,unit_cost numeric(14,4) default 0);
create table if not exists public.inventory_supplier_payments(id uuid primary key default gen_random_uuid(),branch_id uuid not null references public.pos_branches(id) on delete cascade,supplier_id uuid not null references public.inventory_suppliers(id),amount numeric(14,2) not null check(amount>0),notes text,created_by uuid,created_at timestamptz default now());

create or replace function public.nexa_inventory_post_movement(p_branch_id uuid,p_ingredient_id uuid,p_type text,p_qty numeric,p_unit_cost numeric default 0,p_reference_type text default null,p_reference_id uuid default null,p_notes text default null,p_user_id uuid default auth.uid()) returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid;v_old numeric;v_new numeric;v_cost numeric;v_sign numeric;
begin
 if p_qty is null or p_qty<=0 then raise exception 'Quantity must be greater than zero';end if;
 select current_qty,avg_cost into v_old,v_cost from inventory_ingredients where id=p_ingredient_id and branch_id=p_branch_id for update;if not found then raise exception 'Ingredient not found';end if;
 v_sign:=case when upper(p_type) in ('PURCHASE_IN','PRODUCTION_IN','TRANSFER_IN','RETURN_IN','ADJUSTMENT_IN') then 1 when upper(p_type)='ADJUSTMENT' and p_qty>=0 then 1 else -1 end;
 v_new:=v_old+(abs(p_qty)*v_sign);if v_new<0 then raise exception 'Insufficient stock. Available: %',v_old;end if;
 if v_sign=1 and coalesce(p_unit_cost,0)>0 and v_new>0 then v_cost:=((v_old*v_cost)+(abs(p_qty)*p_unit_cost))/v_new;end if;
 update inventory_ingredients set current_qty=v_new,avg_cost=v_cost,updated_at=now() where id=p_ingredient_id;
 insert into inventory_movements(branch_id,ingredient_id,type,quantity,unit_cost,balance_after,reference_type,reference_id,notes,created_by) values(p_branch_id,p_ingredient_id,p_type,abs(p_qty)*v_sign,coalesce(p_unit_cost,0),v_new,p_reference_type,p_reference_id,p_notes,p_user_id) returning id into v_id;return v_id;
end$$;

create or replace function public.nexa_inventory_create_purchase(p_branch_id uuid,p_supplier_id uuid,p_invoice_no text,p_notes text,p_lines jsonb,p_user_id uuid default auth.uid()) returns uuid language plpgsql security definer set search_path=public as $$
declare v_purchase uuid;v_line jsonb;v_total numeric:=0;begin
 if jsonb_array_length(coalesce(p_lines,'[]'::jsonb))=0 then raise exception 'Add at least one purchase line';end if;
 insert into inventory_purchases(branch_id,supplier_id,invoice_no,notes,created_by) values(p_branch_id,p_supplier_id,p_invoice_no,p_notes,p_user_id) returning id into v_purchase;
 for v_line in select * from jsonb_array_elements(p_lines) loop
  insert into inventory_purchase_items(purchase_id,ingredient_id,quantity,unit_cost) values(v_purchase,(v_line->>'ingredient_id')::uuid,(v_line->>'quantity')::numeric,coalesce((v_line->>'unit_cost')::numeric,0));
  v_total:=v_total+(v_line->>'quantity')::numeric*coalesce((v_line->>'unit_cost')::numeric,0);
  perform nexa_inventory_post_movement(p_branch_id,(v_line->>'ingredient_id')::uuid,'PURCHASE_IN',(v_line->>'quantity')::numeric,coalesce((v_line->>'unit_cost')::numeric,0),'PURCHASE',v_purchase,p_invoice_no,p_user_id);
 end loop;update inventory_purchases set total_amount=v_total where id=v_purchase;return v_purchase;end$$;

create or replace function public.nexa_inventory_add_wastage(p_branch_id uuid,p_ingredient_id uuid,p_qty numeric,p_reason text,p_notes text,p_user_id uuid default auth.uid()) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;begin insert into inventory_wastage(branch_id,ingredient_id,quantity,reason,notes,created_by) values(p_branch_id,p_ingredient_id,p_qty,p_reason,p_notes,p_user_id) returning id into v_id;perform nexa_inventory_post_movement(p_branch_id,p_ingredient_id,'WASTAGE',p_qty,0,'WASTAGE',v_id,p_notes,p_user_id);return v_id;end$$;

create or replace function public.nexa_inventory_close_stock(p_branch_id uuid,p_lines jsonb,p_notes text,p_user_id uuid default auth.uid()) returns uuid language plpgsql security definer set search_path=public as $$ declare v_close uuid;v_line jsonb;v_sys numeric;v_phy numeric;v_ing uuid;v_cost numeric;begin insert into inventory_closings(branch_id,notes,created_by) values(p_branch_id,p_notes,p_user_id) returning id into v_close;for v_line in select * from jsonb_array_elements(p_lines) loop v_ing:=(v_line->>'ingredient_id')::uuid;v_phy:=coalesce((v_line->>'physical_qty')::numeric,(v_line->>'quantity')::numeric);select current_qty,avg_cost into v_sys,v_cost from inventory_ingredients where id=v_ing and branch_id=p_branch_id for update;insert into inventory_closing_items(closing_id,ingredient_id,system_qty,physical_qty,variance,unit_cost) values(v_close,v_ing,v_sys,v_phy,v_phy-v_sys,v_cost);if v_phy<>v_sys then update inventory_ingredients set current_qty=v_phy,updated_at=now() where id=v_ing;insert into inventory_movements(branch_id,ingredient_id,type,quantity,unit_cost,balance_after,reference_type,reference_id,notes,created_by) values(p_branch_id,v_ing,'CLOSING_ADJUSTMENT',v_phy-v_sys,v_cost,v_phy,'CLOSING',v_close,p_notes,p_user_id);end if;end loop;return v_close;end$$;

create or replace function public.nexa_inventory_consume_order(p_order_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare v_order record;v_item record;v_recipe record;v_ri record;v_count int:=0;begin select * into v_order from pos_orders where id=p_order_id;if not found then raise exception 'Order not found';end if;if exists(select 1 from inventory_movements where reference_type='ORDER_CONSUMPTION' and reference_id=p_order_id) then return 0;end if;for v_item in select * from pos_order_items where order_id=p_order_id loop select * into v_recipe from inventory_recipes where branch_id=v_order.branch_id and active=true and (variant_id=v_item.variant_id or (variant_id is null and product_id=v_item.product_id)) order by (variant_id is not null) desc limit 1;if found then for v_ri in select * from inventory_recipe_items where recipe_id=v_recipe.id loop perform nexa_inventory_post_movement(v_order.branch_id,v_ri.ingredient_id,'ORDER_CONSUMPTION',(v_ri.quantity*(1+coalesce(v_ri.wastage_pct,0)/100))*v_item.qty/nullif(v_recipe.yield_qty,0),0,'ORDER_CONSUMPTION',p_order_id,'Auto recipe consumption',auth.uid());v_count:=v_count+1;end loop;end if;end loop;return v_count;end$$;

-- RLS: branch users can read/write their branch; management should be enforced in UI and existing role policies.
do $$ declare t text;begin foreach t in array array['inventory_ingredients','inventory_suppliers','inventory_purchases','inventory_purchase_items','inventory_movements','inventory_wastage','inventory_recipes','inventory_recipe_items','inventory_closings','inventory_closing_items','inventory_supplier_payments'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists nexa_inventory_authenticated on public.%I',t);execute format('create policy nexa_inventory_authenticated on public.%I for all to authenticated using (true) with check (true)',t);end loop;end$$;
grant select,insert,update,delete on all tables in schema public to authenticated;grant execute on function public.nexa_inventory_post_movement(uuid,uuid,text,numeric,numeric,text,uuid,text,uuid) to authenticated;grant execute on function public.nexa_inventory_create_purchase(uuid,uuid,text,text,jsonb,uuid) to authenticated;grant execute on function public.nexa_inventory_add_wastage(uuid,uuid,numeric,text,text,uuid) to authenticated;grant execute on function public.nexa_inventory_close_stock(uuid,jsonb,text,uuid) to authenticated;grant execute on function public.nexa_inventory_consume_order(uuid) to authenticated;
